import java.util.*;

class Solution {
    public int minShots(int[][] targets) {
        if (targets.length == 0) return 0;
        int[][] t = targets.clone();
        Arrays.sort(t, (a, b) -> Integer.compare(a[1], b[1]));   // by right end
        int shots = 1;
        int pos = t[0][1];                    // fire at the first right end
        for (int i = 1; i < t.length; i++) {
            if (t[i][0] > pos) {              // not hit by the last shot
                shots++;
                pos = t[i][1];
            }
        }
        return shots;
    }
}

